Here is the problem description:
<problem_description>
Little Johnny Bubbles enjoys spending hours in front of his computer playing video games. His favorite game is Bubble Strike, fast-paced bubble shooting online game for two players.Each game is set in one of the N maps, each having different terrain configuration. First phase of each game decides on which map the game will be played. The game system randomly selects three maps and shows them to the players. Each player must pick one of those three maps to be discarded. The game system then randomly selects one of the maps that were not picked by any of the players and starts the game.Johnny is deeply enthusiastic about the game and wants to spend some time studying maps, thus increasing chances to win games played on those maps. However, he also needs to do his homework, so he does not have time to study all the maps. That is why he asked himself the following question: "What is the minimum number of maps I have to study, so that the probability to play one of those maps is at least $$$P$$$"?Can you help Johnny find the answer for this question? You can assume Johnny's opponents do not know him, and they will randomly pick maps.
</problem_description>

Here is the Java 11 code you have to repair:
<original_code>
import java.io.*;
import java.util.*;

public class I {

    public static boolean DEBUG = true;
    public static String name = "I";

    public static void main(String[] args) throws IOException {
        FastScanner scan;
        PrintWriter out;
        if (DEBUG) {
            scan = new FastScanner(System.in);
            out = new PrintWriter(System.out);
        } else {
            scan = new FastScanner(name + ".in");
            out = new PrintWriter(new BufferedWriter(new FileWriter(name + ".out")));
        }

        float N = Float.parseFloat(scan.nextString());
        float P = Float.parseFloat(scan.nextString());

        for(int i=0; i<=N; i+=1) {
            double val = (i*(i-1)*(i-2))/6.0 + (i*(i-1)*(N-i))/2.0 + (i*(N-i)*(N-i-1))/4.0;
            val = val / ((N*(N-1)*(N-2))/6.0);

            if(val >= P) {
                out.println((int)i);
                break;
            }
        }

        out.close();
    }

    static class BIT {
        public int[] tree;

        public BIT(int len) {
          tree = new int[len+5];
        }

        public void update(int index, int val) {
          index++;
          while(index < tree.length) {
            tree[index] ^= val;
            index += index & -index;
          }
        }

        public int query(int index) {
          int result = 0;
          index++;
          while(index > 0) {
            result ^= tree[index];
            index -= index & -index;
          }

          return result;
        }

        public int rangeSum(int low, int high) {
          return query(high) - query(low-1);   
        }

      }

    static ArrayList<Integer>[] adjList;
    static int[] tin, tout;
    static int[][] BL;
    static int ct;

    public static void preprocess(int root) {
        ct = 0;
        tin = new int[adjList.length];
        tout = new int[adjList.length];
        BL = new int[adjList.length][log2(adjList.length)+1];

        recur_bl(root,root);
    }

    public static void recur_bl(int v, int p) {
        tin[v] = ++ct;
        BL[v][0] = p;
        for (int i=1; i <= log2(adjList.length); ++i) BL[v][i] = BL[BL[v][i-1]][i-1];

        for (int i=0; i<adjList[v].size(); i++) if(adjList[v].get(i) != p) recur_bl(adjList[v].get(i), v);

        tout[v] = ++ct;
    }

    public static boolean is_ancestor(int u, int v) {
        return tin[u] <= tin[v] && tout[u] >= tout[v];
    }

    public static int lca(int u, int v) {
        if(is_ancestor(u, v)) return u;
        if(is_ancestor(v, u)) return v;

        for(int i=log2(adjList.length); i >= 0; --i) if(!is_ancestor(BL[u][i], v)) u = BL[u][i];

        return BL[u][0];
    }

    public static int log2(int n) {
        return (int)Math.ceil(Math.log10(n)/Math.log10(2));
    }

    static class FastScanner {
        InputStream dis;
        byte[] buffer = new byte[1 << 17];
        int pointer = 0;

        public FastScanner (String fileName) throws IOException {
            dis = new FileInputStream(fileName);
        }

        public FastScanner (InputStream is) throws IOException {
            dis = is;
        }

        int nextInt() throws IOException {
            int ret = 0;

            byte b;
            do {
                b = nextByte();
            } while (b <= ' ');
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = nextByte();
            }
            while (b >= '0' && b <= '9') {
                ret = 10 * ret + b - '0';
                b = nextByte();
            }

            return (negative) ? -ret : ret;
        }

        long nextLong() throws IOException {
            long ret = 0;

            byte b;
            do {
                b = nextByte();
            } while (b <= ' ');
            boolean negative = false;
            if (b == '-') {
                negative = true;
                b = nextByte();
            }
            while (b >= '0' && b <= '9') {
                ret = 10 * ret + b - '0';
                b = nextByte();
            }

            return (negative) ? -ret : ret;
        }

        byte nextByte() throws IOException {
            if (pointer == buffer.length) {
                dis.read(buffer, 0, buffer.length);
                pointer = 0;
            }
            return buffer[pointer++];
        }

        String nextString() throws IOException {
            StringBuilder ret = new StringBuilder();

            byte b;
            do {
                b = nextByte();
            } while (b <= ' ');
            while (b > ' ') {
                ret.appendCodePoint(b);
                b = nextByte();
            }

            return ret.toString();
        }

    }
}
